CREATE TABLE task_refs (
    task_id TEXT NOT NULL REFERENCES collection_tasks(id),
    repository_id INTEGER NOT NULL,
    ref_id TEXT NOT NULL,
    PRIMARY KEY (task_id, repository_id, ref_id),
    FOREIGN KEY (repository_id, ref_id) REFERENCES activity_refs(repository_id, id)
  );
CREATE INDEX hits_repository_observation
    ON hits (repository_id, fetched_at, subquery_id, path);
CREATE INDEX repository_observations_repository
    ON repository_observations (repository_id);
CREATE INDEX collection_pages_task
    ON collection_pages (task_id);
CREATE INDEX collection_tasks_repository
    ON collection_tasks (repository_id);
CREATE INDEX collection_attempts_repository
    ON collection_attempts (repository_id, invocation_id, kind);
COMMIT;
